def build_agent(sandbox):
    # Create the hull with low density to ensure buoyancy
    hull = sandbox.add_beam(x=5.0, y=1.0, width=2.0, height=1.0, density=200)

    # Create paddles for propulsion with lower density to save mass
    paddle1 = sandbox.add_beam(x=4.5, y=1.0, width=0.5, height=0.5, density=100)
    joint1 = sandbox.add_joint(hull, paddle1, anchor_point=(4.5, 1.0), type='rigid')

