def agent_action(sandbox, agent_body, step_count):
    # Find all paddles in the environment
    paddles = []
    for body in sandbox.bodies:
        if body.width == 0.5 and body.height == 0.5:
            paddles.append(body)

    # Track last used step for each paddle to enforce cooldown
    last_used = {}
    for paddle in paddles:
        if paddle not in last_used:
            last_used[paddle] = step_count - 3  # Initialize with a step before the first use
        if step_count >= last_used[paddle] + 3:
            # Apply forward force to paddle
            sandbox.apply_force(paddle, fx=520, fy=0, step_count=step_count)
            last_used[paddle] = step_count
